4	import type { Email } from './types';
5	
6	const SCOPES = ['https://www.googleapis.com/auth/gmail.readonly'];
7	
8	export function getOAuthClient() {
9	  return new google.auth.OAuth2(
10	    process.env.GOOGLE_CLIENT_ID,
11	    process.env.GOOGLE_CLIENT_SECRET,
12	    `${process.env.NEXT_PUBLIC_APP_URL}/api/auth/google`
13	  );
14	}
15	
16	export function getAuthUrl(): string {
17	  const oauth2Client = getOAuthClient();
18	  return oauth2Client.generateAuthUrl({
19	    access_type: 'online',
20	    scope: SCOPES,
21	    prompt: 'consent',
22	  });
23	}
24	
25	export async function exchangeCodeForToken(code: string): Promise<string> {
26	  const oauth2Client = getOAuthClient();
27	  const { tokens } = await oauth2Client.getToken(code);
28	
29	  if (!tokens.access_token) {
30	    throw new Error('No access token received');
31	  }
32	
33	  return tokens.access_token;
34	}
35	
36	export async function fetchGmailEmails(accessToken: string, count: number = 50): Promise<Email[]> {
37	  const oauth2Client = getOAuthClient();
38	  oauth2Client.setCredentials({ access_token: accessToken });
39	
40	  const gmail = google.gmail({ version: 'v1', auth: oauth2Client });
41	
42	  const listRes = await gmail.users.messages.list({
43	    userId: 'me',
44	    maxResults: count,
45	    q: '',
46	  });
47	
48	  const messages = listRes.data.messages || [];
49	  if (messages.length === 0) return [];
50	
51	  const emailPromises = messages.map(async (msg) => {
52	    try {
53	      const res = await gmail.users.messages.get({
54	        userId: 'me',
55	        id: msg.id!,
56	        format: 'full',
57	      });
58	
59	      return parseGmailMessage(res.data);
60	    } catch {
61	      return null;
62	    }
63	  });
64	
65	  const results = await Promise.all(emailPromises);
66	  return results.filter((email): email is Email => email !== null);
67	}
68	
69	function parseGmailMessage(message: any): Email {
70	  const headers = message.payload?.headers || [];
71	  const getHeader = (name: string) =>
72	    headers.find((header: any) => header.name.toLowerCase() === name.toLowerCase())?.value || '';
73	
74	  // Parse "Name <email@domain.com>" format
75	  function parseFromHeader(from: string): { fromName: string | null; fromEmail: string | null } {
76	    const match = from.match(/^"?([^"<]*)"?\s*<?([^>]*)>?$/);
77	    if (match) {
78	      const name = match[1].trim() || null;
79	      const email = match[2].trim() || null;
80	      return { fromName: name || null, fromEmail: email || from };
81	    }
82	    return { fromName: null, fromEmail: from };
83	  }
84	
85	  const body = extractBody(message.payload);
86	  const from = getHeader('From');
87	  const { fromName, fromEmail } = parseFromHeader(from);
88	
89	  return {
90	    id: message.id || '',
91	    threadId: message.threadId || '',
92	    from,
93	    fromName,
94	    fromEmail,
95	    to: getHeader('To'),
96	    subject: getHeader('Subject'),
97	    date: getHeader('Date'),
98	    body,
99	    snippet: message.snippet || '',
100	    labelIds: message.labelIds || [],
101	  };
102	}
103	
104	function extractBody(payload: any): string {
105	  if (!payload) return '';
106	
107	  if (payload.body?.data) {
108	    return decodeBase64Url(payload.body.data);
